/** The five looks of code (spec/01 §1.8, D67): three muted tones, comments textMuted, everything else text. */
enum class SbCodeLook { Plain, Keyword, String, Constant, Comment }

/** A run of code in one look (the web's sb-tok-* spans). */
@Immutable
data class SbCodeSpan(val text: String, val look: SbCodeLook = SbCodeLook.Plain)

/** The spans as text in their looks; sebaro Mono 500 only, so no bold and no italic. */
@Composable
internal fun sbCodeText(spans: List<SbCodeSpan>): AnnotatedString {
    val c = SebaroTheme.colors
    val s = SebaroTheme.syntax
    return buildAnnotatedString {
        spans.forEach { span ->
            val look = when (span.look) {
                SbCodeLook.Plain -> c.text
                SbCodeLook.Keyword -> s.keyword
                SbCodeLook.String -> s.string
                SbCodeLook.Constant -> s.constant
                SbCodeLook.Comment -> c.textMuted
            }
            withStyle(SpanStyle(color = look)) { append(span.text) }
        }
    }
}

/**
 * The scrolling code area of SbCodeBlock and SbDiff (pre tabindex="0"): long lines scroll sideways inside it, never
 * the screen. It takes the keyboard focus (the inset ring); ← / → scroll by 40 dp (the browsers' step), and an arrow
 * that cannot scroll further passes on. [label] names it for TalkBack (the web's region name). Code reads left to right
 * in every language, so the area stays left to right inside a right-to-left screen.
 */
@Composable
internal fun SbCodeScroller(
    label: String?,
    modifier: Modifier = Modifier,
    content: @Composable () -> Unit,
) {
    val t = SebaroTheme.tokens
    val scroller = rememberScrollState()
    val interaction = remember { MutableInteractionSource() }
    val step = with(LocalDensity.current) { t.space.s10.toPx() }   // 40 dp for each arrow; provisional, agent
    // left to right also on a right-to-left screen: line numbers, sign and code keep their order (provisional, agent;
    // the web's pre and diff lines take the page's direction and reorder the code's punctuation)
    CompositionLocalProvider(LocalLayoutDirection provides LayoutDirection.Ltr) {
        Box(
            modifier
                .sbFocusRingInset(interaction)
                .onPreviewKeyEvent { e ->
                    if (e.type != KeyEventType.KeyDown) return@onPreviewKeyEvent false
                    val delta = when (e.key) {
                        Key.DirectionRight -> step
                        Key.DirectionLeft -> -step
                        else -> return@onPreviewKeyEvent false
                    }
                    scroller.dispatchRawDelta(delta) != 0f
                }
                .then(if (label != null) Modifier.semantics { contentDescription = label } else Modifier)
                .focusable(interactionSource = interaction)
                .horizontalScroll(scroller),
        ) { content() }
    }
}

/**
 * Code block (spec/02 §3.10, the one form): on surfaceSunken, radius container; a bar with [language] (caption
 * textMuted) and the copy button („Kopieren“, then „Kopiert“ for 2 s; the plain code goes to the system clipboard),
 * a hairline under it; then [code] in sebaro Mono (code 14/20) in its five looks, 16 dp inside, without wrapping:
 * long lines scroll sideways inside the block. [label] names the code area for TalkBack.
 */
@Composable
fun SbCodeBlock(code: List<SbCodeSpan>, modifier: Modifier = Modifier, language: String? = null, label: String? = null) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val plain = remember(code) { code.joinToString("") { it.text } }
    Column(modifier.fillMaxWidth().background(c.surfaceSunken, t.shapes.container)) {
        Row(
            Modifier
                .fillMaxWidth()
                .drawBehind {
                    val h = t.borderWidth.hairline.toPx()
                    drawRect(c.border, Offset(0f, size.height - h), Size(size.width, h))
                }
                .padding(start = t.space.s4, end = t.space.s1, bottom = t.borderWidth.hairline),
            horizontalArrangement = Arrangement.spacedBy(t.space.s2),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            // without a language the bar holds only the button (the web leaves the element out): no empty text node
            if (language != null) Text(language, style = ty.caption, color = c.textMuted, modifier = Modifier.weight(1f))
            else Spacer(Modifier.weight(1f))
            SbCodeCopy(plain, language ?: "")
        }
        SbCodeScroller(
            label,
            Modifier
                .fillMaxWidth()
                .clip(RoundedCornerShape(bottomStart = t.radius.container, bottomEnd = t.radius.container)),
        ) {
            Text(sbCodeText(code), style = ty.code, softWrap = false, modifier = Modifier.padding(t.space.s4))
        }
    }
}

/** A code block of plain code in one look (unhighlighted code is text, spec/02 §3.10). */
@Composable
fun SbCodeBlock(code: String, modifier: Modifier = Modifier, language: String? = null, label: String? = null) {
    SbCodeBlock(listOf(SbCodeSpan(code)), modifier, language, label)
}

/** The copy button of the bar (sb-code__copy): glyph and word, the word „Kopiert“ for 2 s after a press. */
@Composable
private fun SbCodeCopy(plain: String, clipLabel: String) = SbCopyButton(plain, clipLabel = clipLabel, form = SbCopyForm.Code)

/** Copy outside a code block follows spec/02 §1.2; the code bar follows §3.10 (provisional, agent). */
enum class SbCopyForm { Code, Secondary }

/** Public copy key: custom action label, persistent result announcement, 2 s visible result.
 * The caller modifier belongs to the outer Box, including Row weight and Column alignment parent data. */
@Composable
fun SbCopyButton(plain: String, modifier: Modifier = Modifier, clipLabel: String = "", enabled: Boolean = true, sensitive: Boolean = false, onCopied: () -> Unit = {}, label: String? = null, form: SbCopyForm = SbCopyForm.Secondary) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val m = sbMessages()
    val context = LocalContext.current
    val interaction = remember { MutableInteractionSource() }
    val pressed by interaction.collectIsPressedAsState()
    val hovered by interaction.collectIsHoveredAsState()
    var presses by remember { mutableIntStateOf(0) }
    var copied by remember { mutableStateOf(false) }
    var announcement by remember { mutableStateOf<String?>(null) }
    LaunchedEffect(presses) {
        if (presses > 0) {
            copied = true
            // Empty for one frame permits the same result to be announced on another successful press.
            announcement = null
            withFrameNanos { }
            announcement = m.codeCopied
            delay(2000)
            copied = false
        }
    }
    val copy: () -> Unit = {
        val clipboard = context.getSystemService(ClipboardManager::class.java)
        if (clipboard != null) {
            val clip = ClipData.newPlainText(clipLabel, plain)
            if (sensitive) clip.description.extras = android.os.PersistableBundle().apply {
                val key = if (android.os.Build.VERSION.SDK_INT >= 33) android.content.ClipDescription.EXTRA_IS_SENSITIVE
                    else "android.content.extra.IS_SENSITIVE"
                putBoolean(key, true)
            }
            clipboard.setPrimaryClip(clip)
            onCopied()
            presses++
        }
    }
    Box(modifier, propagateMinConstraints = true) {
        val word = if (copied) m.codeCopied else label ?: m.codeCopy
        if (form == SbCopyForm.Secondary) {
            SbSecondaryAction(word, copy, Modifier, SebaroIcons.Outline.Copy, enabled)
        } else {
            Row(
                Modifier
                    .sbFocusRing(interaction, t.radius.control)
                    .heightIn(min = t.size.targetTouch)
                    .background(if (enabled && (pressed || hovered)) c.pressedFill else Color.Transparent, t.shapes.control)
                    .clickable(enabled = enabled, interactionSource = interaction, indication = null, role = Role.Button, onClick = copy)
                    .padding(horizontal = t.space.s3),
                horizontalArrangement = Arrangement.spacedBy(t.space.s1),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Icon(SebaroIcons.Outline16.Copy, contentDescription = null, tint = c.textMuted, modifier = Modifier.size(t.size.iconSm))
                Text(word, style = SebaroTheme.typography.label, color = if (enabled) c.text else c.textMuted)
            }
        }
        // Sibling of the clickable/merged key: resetting its visible word never changes this status.
        SbStatusRegion(announcement)
    }
}

/** Previous source and binary/default-argument entry point, including trailing onCopied lambdas. */
@Composable
fun SbCopyButton(plain: String, modifier: Modifier = Modifier, clipLabel: String = "", enabled: Boolean = true, sensitive: Boolean = false, onCopied: () -> Unit = {}) {
    SbCopyButton(plain, modifier, clipLabel, enabled, sensitive, onCopied, null, SbCopyForm.Secondary)
}

